def compute(vars):
    total_net_revenue = vars["v1"] + vars["v2"]
    return {
        "value": total_net_revenue,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "total_net_revenue": total_net_revenue,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
